// Ask PayPal whether a webhook delivery really came from it. rawBody must be the
// request body exactly as received; re-serializing the parsed JSON can change it
// and make verification fail.
export async function verifyWebhookSignature(headers, rawBody) {
  const webhookId = process.env.PAYPAL_WEBHOOK_ID;
  if (!webhookId) {
    throw new Error("Missing PAYPAL_WEBHOOK_ID: cannot verify webhook signatures.");
  }
  const fields = {
    auth_algo: headers["paypal-auth-algo"],
    cert_url: headers["paypal-cert-url"],
    transmission_id: headers["paypal-transmission-id"],
    transmission_sig: headers["paypal-transmission-sig"],
    transmission_time: headers["paypal-transmission-time"],
    webhook_id: webhookId,
  };
  if (Object.values(fields).some((value) => !value) || !rawBody?.length) {
    return false;
  }

  const accessToken = await generateAccessToken();
  // Splice the raw event in as-is instead of JSON.stringify-ing the parsed body.
  const body = `${JSON.stringify(fields).slice(0, -1)},"webhook_event":${rawBody.toString("utf8")}}`;
  const response = await fetch(`${base}/v1/notifications/verify-webhook-signature`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${accessToken}`,
    },
    body,
  });

  const { jsonResponse, httpStatusCode } = await handleResponse(response);
  return httpStatusCode === 200 && jsonResponse.verification_status === "SUCCESS";
}

